(()=>{'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const topics=()=>window.COURSE_TOPICS.filter(t=>t.chapter===1),data=window.CHAPTER_ONE;let active=null,audio=null,audioToken=0,lastAudioSave=0;
function progress(id){const raw=CircuitStore.get('guided')?.[id]?.rulesAndCases||{},d=data[id],state={case:Math.max(0,Math.min(d.cases.length-1,Math.trunc(Number(raw.case)||0))),steps:{},seen:{},audio:{},quizzes:{},practiceOpen:raw.practiceOpen===true,question:Math.max(0,Math.trunc(Number(raw.question)||0))};for(const c of d.cases){state.steps[c.id]=Math.max(0,Math.min(c.steps.length-1,Math.trunc(Number(raw.steps?.[c.id])||0)));state.seen[c.id]=raw.seen?.[c.id]===true;for(let i=0;i<c.steps.length;i++){const key=c.id+':'+i,t=Number(raw.audio?.[key]);if(Number.isFinite(t)&&t>=0)state.audio[key]=t;}}const qs=window.QUESTIONS.filter(q=>q.topic===id);for(const q of qs){const x=raw.quizzes?.[q.id];if(!x||typeof x!=='object')continue;state.quizzes[q.id]={input:typeof x.input==='string'?x.input.slice(0,100):'',selected:Number.isInteger(x.selected)&&q.type==='choice'&&x.selected>=0&&x.selected<q.choices.length?x.selected:null,checked:x.checked===true,correct:x.correct===true};}return state;}
function save(){if(!active)return;const all=CircuitStore.get('guided')||{};all[active.id]??={};all[active.id].rulesAndCases=active.p;CircuitStore.set('guided',all);}
function stop(){window.CircuitVideos?.stop();window.CircuitFoundation?.stop();audioToken++;if(audio){if(active&&!audio.ended){active.p.audio[audio.dataset.position]=audio.currentTime;save();}audio.pause();audio=null;}}
function overview(){const finished=new Set(window.CircuitStore?.get('app')?.reviewed||[]);return `<section class="c1"><div class="c1-breadcrumb"><a href="#chapters">← All chapters</a><span>CHAPTER 01</span></div><div class="c1-overview-head"><span class="c1-eyebrow">BASIC CONCEPTS & LAWS</span><h1>Watch. Keep the rules.<br>Then practise.</h1><p class="c1-chapter-completion">${topics().filter(t=>finished.has(t.id)).length} of 10 lessons marked finished</p><p>Start with what charge and energy do. Learn to label a circuit, then use its laws to find an unknown.</p></div><section class="cf-roadmap"><div><span class="c1-eyebrow">YOUR ROUTE THROUGH THE CHAPTER</span><h2>From a physical idea to a useful calculation.</h2><ol><li><b>Build the meaning · 1.1–1.3</b><span>Source, load, current, voltage, EMF and connection conditions.</span></li><li><b>Choose and read references · 1.4–1.5</b><span>Signs, potential, element behavior and absorbed or supplied power.</span></li><li><b>Find a simpler route to the unknown · 1.6–1.10</b><span>Transform sources, identify topology, apply circuit laws and use equivalent circuits.</span></li></ol></div><aside><h3>Before you begin</h3><p>You need basic algebra and unit conversions. New quantities are explained where you meet them.</p><h3>What success looks like</h3><p>You can explain a symbol, state when a rule applies, read its diagram and check whether the result makes physical sense.</p><a href="#topic/1.1">Start with the foundations →</a></aside></section><div class="c1-overview-grid">${topics().map(t=>`<a class="c1-topic-card" href="#topic/${t.id}"><div class="c1-topic-card-top"><div class="c1-topic-card-top"><span class="c1-topic-id">${t.id}</span><span class="c1-completion ${finished.has(t.id)?'is-finished':''}">${finished.has(t.id)?'✓ Finished':'Not marked finished'}</span></div><span class="c1-completion ${finished.has(t.id)?'is-finished':''}">${finished.has(t.id)?'✓ Finished':'Not marked finished'}</span></div><h2>${data[t.id].title}</h2><p>${data[t.id].goal}</p><span class="c1-card-footer">${window.CircuitVideos?.count(t.id)||0} full video${window.CircuitVideos?.count(t.id)===1?'':'s'} + cheat sheets <span>Open topic ↗</span></span></a>`).join('')}</div><p class="c1-source-note">Each full video belongs to one lesson. Its cheat sheet sits directly below it; exercises open separately. All original teaching and teacher references remain available. Completion is your own mark, separate from watching progress and exercise scores.</p></section>`;}
function page(t,reviewed){const d=data[t.id],n=topics().findIndex(x=>x.id===t.id),finished=reviewed;return `<section class="c1 c1-video-first" id="c1-page"><div class="c1-breadcrumb"><a href="#chapter/1">← Chapter 1 · all lessons</a><span>WATCH · KEEP THE RULES · PRACTISE</span><span class="c1-save" data-study-save role="status"></span></div><div class="c1-heading"><div><span class="c1-eyebrow">LESSON ${t.id} · ${esc(t.title)}</span><h1>${d.title}</h1><p>${d.goal}</p></div><div class="c1-heading-controls"><label class="c1-topic-select">Jump to a lesson<select id="c1-topic">${topics().map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${x.id} · ${data[x.id].title}</option>`).join('')}</select></label><button id="review-topic" class="c1-finish-button" aria-pressed="${finished}">${finished?'✓ Lesson finished':'Mark lesson finished'}</button><small class="c1-finish-note">Your own completion mark · not a test score</small></div></div>${window.CircuitVideos?.renderTopic(t.id)||''}<div class="c1-lesson-actions"><div><h2>Ready to apply it?</h2><p>Exercises open in their own section. Use the same references and units as the cheat sheet.</p></div><a id="c1-practise" class="c1-practise-button" href="#practice/topic/${t.id}">Open lesson ${t.id} exercises →</a><button type="button" class="c1-finish-button" data-c1-finish aria-pressed="${finished}">${finished?'✓ Lesson finished':'Mark lesson finished'}</button></div><div class="c1-after"><span>Cheat-sheet reading size</span><div class="c1-text-size" role="group" aria-label="Reading size"><button id="reading-smaller" aria-label="Decrease lesson text size">A−</button><output id="reading-size-value" aria-live="polite">22px</output><button id="reading-larger" aria-label="Increase lesson text size">A+</button></div></div><details class="c1-optional-teaching"><summary>More explanations and interactive diagrams <span>Optional ↗</span></summary>${window.CircuitFoundation?.supports(t.id)?'<div id="c1-teaching-root"></div>':'<div id="c1-case-list" class="c1-case-list" role="tablist" aria-label="Cases in this topic"></div><div id="c1-workspace"></div>'}</details><details class="c1-reference" id="c1-reference"><summary><span>Complete taught material & teacher examples</span><span>Lesson ${t.id} · view reference ↗</span></summary><p class="c1-source-note">The complete original reviewed lesson remains available for its diagrams, derivations and additional examples.</p><div class="article">${t.html}</div></details><div class="c1-topic-footer">${n?`<a href="#topic/${topics()[n-1].id}">← Previous lesson</a>`:'<a href="#chapter/1">← All Chapter 1 lessons</a>'}${n<topics().length-1?`<a href="#topic/${topics()[n+1].id}">Next lesson ${topics()[n+1].id} →</a>`:'<a href="#chapter/1">Chapter 1 overview →</a>'}</div></section>`;}
function mount(options={}){stop();const id=location.hash.split('/')[1];if(!data[id]||(!$('#c1-workspace')&&!$('#c1-teaching-root'))){active=null;return;}window.CircuitGuided?.stop();active={id,d:data[id],p:progress(id),options};$('#c1-topic').onchange=e=>location.hash='#topic/'+e.target.value;document.querySelectorAll('[data-c1-finish]').forEach(b=>b.onclick=()=>$('#review-topic').click());if($('#c1-teaching-root')){window.CircuitFoundation.mount($('#c1-teaching-root'),id,()=>location.hash='#practice/topic/'+id);}else draw();window.CircuitVideos?.mount($('#c1-page'));}
function draw(){const {d,p}=active,c=d.cases[p.case],i=p.steps[c.id]||0,s=c.steps[i];$('#c1-case-list').innerHTML=d.cases.map((x,j)=>`<button role="tab" tabindex="${j===p.case?0:-1}" aria-selected="${j===p.case}" aria-controls="c1-workspace" data-c1-case="${j}" class="${j===p.case?'selected':''}"><span>${String(j+1).padStart(2,'0')}</span>${esc(x.name)}</button>`).join('');
 $('#c1-workspace').innerHTML=`<div class="c1-workbench" role="tabpanel" aria-label="${esc(c.name)}"><div class="c1-visual-panel"><div class="c1-figure-heading"><span>THE CIRCUIT / THE CASE</span><span>${String(p.case+1).padStart(2,'0')} / ${String(d.cases.length).padStart(2,'0')}</span></div><div class="c1-diagram">${ChapterOneFigure.render(c.figure,i)}</div><div class="c1-visual-bottom"><span class="c1-legend"><i></i>Follow the marked references</span><span>Illustrative or course example</span></div></div><div class="c1-solve-panel"><div class="c1-rule"><span class="c1-eyebrow">THE RULE</span><h2>${esc(c.rule)}</h2><p><b>Apply it:</b> ${esc(c.when)}</p><div class="c1-symbols"><h3>Symbols & terms in this case</h3><dl>${c.symbols.map(([symbol,meaning])=>`<div><dt>${esc(symbol)}</dt><dd>${esc(meaning)}</dd></div>`).join('')}</dl></div></div><div class="c1-example"><span class="c1-eyebrow">WORKED CASE</span><p class="c1-given">${esc(c.given)}</p><div class="c1-step-index" role="group" aria-label="Worked steps">${c.steps.map((st,j)=>`<button data-c1-step="${j}" aria-pressed="${i===j}" aria-label="Step ${j+1}: ${esc(st.label)}" class="${i===j?'active':''}">${j+1}</button>`).join('')}<span>STEP ${i+1} OF ${c.steps.length}</span></div><h3>${esc(s.label)}</h3><div class="c1-equation" aria-label="Calculation">${esc(s.equation).replace(/; /g,'<br>')}</div><p class="c1-why">${esc(s.why)}</p><div class="c1-step-controls"><button id="c1-hear" class="c1-hear" aria-label="Hear this worked step">◖)) <span>Hear this step</span></button><div><button id="c1-prev" aria-label="Previous worked step" ${i===0?'disabled':''}>←</button><button id="c1-next" class="c1-primary">${i<c.steps.length-1?'Next step →':p.case<d.cases.length-1?'Next case →':'Back to topic list →'}</button></div></div><div id="c1-player" class="c1-player"></div><p id="c1-audio-status" role="status" class="c1-audio-status">${p.audio[c.id+':'+i]>1?'Voice position saved. Hear this step to resume.':''}</p></div>${c.trap?`<div class="c1-trap"><span>WATCH THE DIFFERENCE</span><p>${esc(c.trap)}</p></div>`:''}</div></div>`;
 document.querySelectorAll('[data-c1-case]').forEach(b=>{b.onclick=()=>selectCase(Number(b.dataset.c1Case));b.onkeydown=e=>{let n=Number(b.dataset.c1Case);if(e.key==='ArrowRight')n=(n+1)%d.cases.length;else if(e.key==='ArrowLeft')n=(n+d.cases.length-1)%d.cases.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=d.cases.length-1;else return;e.preventDefault();selectCase(n);document.querySelector('[data-c1-case="'+n+'"]').focus({preventScroll:true});};});document.querySelectorAll('[data-c1-step]').forEach(b=>b.onclick=()=>selectStep(Number(b.dataset.c1Step)));$('#c1-prev').onclick=()=>selectStep(i-1);$('#c1-next').onclick=()=>{if(i<c.steps.length-1)selectStep(i+1);else if(p.case<d.cases.length-1)selectCase(p.case+1);else location.hash='#chapter/1';};$('#c1-hear').onclick=play;
}
function selectCase(n){stop();active.p.case=n;active.p.seen[active.d.cases[n].id]=true;save();draw();drawPractice();}
function selectStep(n){const c=active.d.cases[active.p.case];if(n<0||n>=c.steps.length)return;stop();active.p.steps[c.id]=n;save();draw();}
async function play(){const {p,d}=active,c=d.cases[p.case],i=p.steps[c.id],key=c.id+':'+i,s=c.steps[i];if(audio&&!audio.ended){if(audio.paused){try{await audio.play();$('#c1-audio-status').textContent='Playing this step.';}catch{$('#c1-audio-status').textContent='Press the audio player’s Play button to continue.';}}else{audio.pause();$('#c1-audio-status').textContent='Paused. Your place is saved.';}return;}
 const token=audioToken;audio=document.createElement('audio');audio.controls=true;audio.preload='metadata';audio.src=s.audio;audio.dataset.position=key;audio.setAttribute('aria-label','Explanation: '+s.label);$('#c1-player').replaceChildren(audio);audio.onloadedmetadata=()=>{if(token===audioToken&&p.audio[key]>0&&p.audio[key]<audio.duration)audio.currentTime=p.audio[key];};audio.ontimeupdate=()=>{if(token===audioToken&&Date.now()-lastAudioSave>750){lastAudioSave=Date.now();p.audio[key]=audio.currentTime;save();}};audio.onpause=audio.onseeked=()=>{if(token===audioToken){p.audio[key]=audio.currentTime;save();}};audio.onended=()=>{if(token===audioToken){p.audio[key]=0;save();$('#c1-audio-status').textContent='Step finished. Continue when you are ready.';}};audio.onerror=()=>{if(token===audioToken)$('#c1-audio-status').textContent='Voice is unavailable. The short explanation is written above; try the audio player again.';};try{await audio.play();$('#c1-audio-status').textContent='Playing this step.';}catch{$('#c1-audio-status').textContent='Press the audio player’s Play button to hear this step.';}}
function drawPractice(){if(!active||!$('#c1-practice-panel'))return;const {p,id}=active,host=$('#c1-practice-panel');host.hidden=!p.practiceOpen;$('#c1-practise').setAttribute('aria-expanded',String(p.practiceOpen));if(!p.practiceOpen)return;const questions=window.QUESTIONS.filter(q=>q.topic===id),q=questions[p.question%questions.length];if(!q){host.innerHTML='<p>Use the complete practice session for this topic.</p>';return;}const a=p.quizzes[q.id]??={input:'',selected:null,checked:false,correct:false};
 host.innerHTML=`<div class="c1-practice-heading"><div><span class="c1-eyebrow">YOUR TURN · TOPIC ${id}</span><h2>Use the rule yourself.</h2></div><span>${p.question%questions.length+1} / ${questions.length}</span></div><p class="c1-practice-prompt">${esc(q.prompt)}</p>${q.type==='choice'?`<div class="c1-options">${q.choices.map((choice,i)=>`<button data-c1-answer="${i}" aria-pressed="${a.selected===i}" class="${a.checked&&i===q.answer?'correct':''} ${a.checked&&!a.correct&&a.selected===i?'incorrect':''}" ${a.checked?'disabled':''}>${esc(choice)}</button>`).join('')}</div>`:`<label class="c1-number-label">Your answer (${esc(q.unit||'value')})<input id="c1-number" inputmode="decimal" value="${esc(a.input)}" placeholder="Enter your answer" ${a.checked?'disabled':''}></label>`}<div class="c1-check-actions"><button class="c1-primary" id="c1-check" ${a.checked?'disabled':''}>Check answer</button>${a.checked?`<button id="c1-another">${questions.length>1?'Try another question':'Try again'}</button>`:''}<span id="c1-question-status" role="status"></span></div>${a.checked?`<div class="c1-feedback ${a.correct?'good':'retry'}"><strong>${a.correct?'Correct.':'Here’s the correction.'}</strong><p>${esc(q.explain)}</p><p>Answer: ${esc(q.type==='choice'?q.choices[q.answer]:q.value+' '+(q.unit||''))}</p></div>`:''}`;
 host.querySelectorAll('[data-c1-answer]').forEach(b=>b.onclick=()=>{if(a.checked)return;a.selected=Number(b.dataset.c1Answer);save();host.querySelectorAll('[data-c1-answer]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});if($('#c1-number'))$('#c1-number').oninput=e=>{a.input=e.target.value;save();};$('#c1-check').onclick=()=>{if(a.checked)return;const given=q.type==='choice'?a.selected:window.STUDY_CORE.parseNumber(a.input);if(given===null||!Number.isFinite(given)){$('#c1-question-status').textContent='Choose or enter an answer first.';return;}a.correct=q.type==='choice'?given===q.answer:Math.abs(given-q.value)<=(q.tol??Math.max(.005,Math.abs(q.value)*.01));a.checked=true;active.options.onAttempt?.(q,a.correct);save();drawPractice();};if($('#c1-another'))$('#c1-another').onclick=()=>{p.question++;const next=questions[p.question%questions.length];delete p.quizzes[next.id];save();drawPractice();};
}
window.ChapterOne={page,overview,mount,stop};document.addEventListener('click',e=>{if(e.target.closest('a[data-circuit-video]'))stop();});window.addEventListener('hashchange',stop);document.addEventListener('visibilitychange',()=>{if(document.hidden&&audio){audio.pause();if(active){active.p.audio[audio.dataset.position]=audio.currentTime;save();}}});
})();
